namespace Gojo.Experiments.PrimitiveMeasure;

/// <summary>Demonstration apparatus assembling existing passages. There is no
/// saturation opcode: behavior resides in ordered rows and their law bytes.
/// Initial bits are supplied observations, not material generated by a step.</summary>
public sealed class PassageFixture
{
    public PortStructure Owner { get; } = new();
    public int[] Ports { get; }
    public PassageConnections Forward { get; }
    public PassageConnections Present { get; }
    public PassageConnections Absent { get; }
    private readonly List<(PassageConnections Table, ConnectionRow Row)> steps = [];
    public IReadOnlyList<(PassageConnections Table, ConnectionRow Row)> Steps => steps.AsReadOnly();

    public PassageFixture(int count, byte initial)
    {
        if (count is < 3 or > 5 || initial >= 1 << count)
            throw new ArgumentOutOfRangeException(nameof(count));
        Ports = Enumerable.Range(0, count).Select(site =>
            Owner.Publish(Owner.Create(0, 0, 1, (ulong)((initial >> site) & 1)))).ToArray();
        Forward = new(Owner, PassageLaw.Unconditional());
        Present = new(Owner, PassageLaw.Controlled());
        Absent = new(Owner, PassageLaw.Controlled(false));
    }

    public ConnectionRow Add(PassageConnections table, int source, int control, int target)
    {
        if (table != Forward && table != Present && table != Absent)
            throw new ArgumentException("Use this fixture's passage tables.", nameof(table));
        var row = table.Connect(Ports.Length <= 4 ? 2 : 3, Ports[source], Ports[control], Ports[target]);
        steps.Add((table, row));
        return row;
    }

    public uint Observe(int visible = -1) => Forward.ObserveScope(Ports,
        visible == -1 ? (1 << Ports.Length) - 1 : visible);

    public uint Predict(uint before)
    {
        foreach (var (table, row) in steps) before = table.PredictScope(row, Ports, before);
        return before;
    }

    public bool TryStep(uint before, out byte after) =>
        PassageConnections.TrySequence(Ports, before, out after, steps.ToArray());

    public byte Stored => Owner.PackedBytes(0, 0, 1)[0];
}
